create extension if not exists "uuid-ossp"; create table if not exists app_users(id uuid primary key default uuid_generate_v4(),email text unique not null,password_hash text not null,full_name text,role text check (role in ('ADMIN','FORMATEUR','PARTICIPANT')) not null,is_active boolean default true,created_at timestamptz default now()); create table if not exists live_sessions(id uuid primary key default uuid_generate_v4(),title text not null,description text,starts_at timestamptz not null,ends_at timestamptz not null,room_name text unique not null,record boolean default true,trainer_id uuid references app_users(id)); create table if not exists recordings(id uuid primary key default uuid_generate_v4(),live_session_id uuid references live_sessions(id),storage_path text not null,duration_seconds int,created_at timestamptz default now()); create table if not exists vod_access(id uuid primary key default uuid_generate_v4(),recording_id uuid references recordings(id),user_id uuid references app_users(id),access_start timestamptz not null,access_end timestamptz not null); create table if not exists live_attendance(id uuid primary key default uuid_generate_v4(),live_session_id uuid references live_sessions(id),user_id uuid references app_users(id),joined_at timestamptz,left_at timestamptz); alter table app_users enable row level security; alter table live_sessions enable row level security; alter table recordings enable row level security; alter table vod_access enable row level security; alter table live_attendance enable row level security;